#!/usr/bin/env bash
#
# One-time setup of the TypEase customer app on a machine WITH the Flutter SDK.
#
# This repository contains only the Dart sources (lib/, test/, integration_test/),
# the translations (assets/), pubspec.yaml and this tool/ folder. The platform
# folders android/ and ios/ are generated by the Flutter tool so that they match
# the installed Flutter version; they are not hand-written here.
#
# What the script does, in order:
#   1. checks that `flutter` is available;
#   2. keeps a copy of the project's own files, runs
#        flutter create --platforms=android,ios --org <ORG> --project-name typease_customer .
#      and puts the project's own files back (lib/, test/, pubspec.yaml, ... are
#      never replaced by template files);
#   3. flutter pub get;
#   4. applies the native configuration (permissions, deep links, usage texts,
#      minimum OS versions) with tool/native/apply_native_config.py;
#   5. flutter analyze;
#   6. flutter test.
#
# IMPORTANT - verification status: this project was written on a machine without
# the Flutter SDK. It has not been compiled or run, and this script itself has
# never been executed with a real Flutter installation. Expect step 5 to report
# problems on the first run; fix them and run the script again (it is safe to
# re-run).
#
# Options (environment variables, all optional):
#   ORG               reverse-domain prefix of the app id      default: ae.typease
#   APP_NAME          name under the icon                      default: TypEase
#   DEEP_LINK_SCHEME  custom URL scheme                        default: typease
#   DEEP_LINK_HOSTS   comma-separated https hosts for Android App Links
#   ANDROID_MIN_SDK   default 23       IOS_MIN_VERSION   default 13.0
#   SKIP_CREATE=1     do not run `flutter create` (platform folders exist and are kept)
#   SKIP_CHECKS=1     stop after step 4 (no analyze / test)
#
# Usage:   tool/bootstrap.sh
#          APP_NAME="Al Noor Typing" ORG=ae.alnoor DEEP_LINK_SCHEME=alnoor tool/bootstrap.sh

set -uo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$PROJECT_DIR" || exit 1

ORG="${ORG:-ae.typease}"
PROJECT_NAME="typease_customer"

step() { printf '\n==> %s\n' "$1"; }
fail() { printf '\nERROR: %s\n' "$1" >&2; exit 1; }

# ---------------------------------------------------------------- 1. Flutter
step "1/6 Checking the Flutter SDK"
if ! command -v flutter >/dev/null 2>&1; then
  fail "The 'flutter' command was not found. Install Flutter 3.24 or newer (https://docs.flutter.dev/get-started/install) and run this script again."
fi
flutter --version || fail "'flutter --version' failed."

# ---------------------------------------------------------------- 2. platform folders
# Files and folders that belong to this repository and must survive `flutter create`.
OWN_PATHS=(lib test integration_test assets tool config pubspec.yaml analysis_options.yaml README.md ARCHITECTURE.md WHITE_LABEL_MOBILE.md SCREEN_ENDPOINT_MAP.md .gitignore)

if [ "${SKIP_CREATE:-0}" = "1" ]; then
  step "2/6 Skipping 'flutter create' (SKIP_CREATE=1)"
elif [ -d android ] && [ -d ios ]; then
  step "2/6 android/ and ios/ already exist - not running 'flutter create' again"
else
  step "2/6 Generating android/ and ios/ with 'flutter create'"
  BACKUP_DIR="$(mktemp -d "${TMPDIR:-/tmp}/typease-bootstrap.XXXXXX")" || fail "Could not create a temporary folder."
  HAD_TEMPLATE_TEST=0
  [ -f test/widget_test.dart ] && HAD_TEMPLATE_TEST=1
  for path in "${OWN_PATHS[@]}"; do
    if [ -e "$path" ]; then
      cp -Rp "$path" "$BACKUP_DIR/" || fail "Could not back up $path."
    fi
  done

  flutter create --platforms=android,ios --org "$ORG" --project-name "$PROJECT_NAME" .
  CREATE_STATUS=$?

  # Put the project's own files back, whatever `flutter create` did to them.
  for path in "${OWN_PATHS[@]}"; do
    if [ -e "$BACKUP_DIR/$path" ]; then
      if [ -d "$BACKUP_DIR/$path" ]; then
        mkdir -p "$path" && cp -Rp "$BACKUP_DIR/$path/." "$path/" || fail "Could not restore $path from $BACKUP_DIR."
      else
        cp -p "$BACKUP_DIR/$path" "$path" || fail "Could not restore $path from $BACKUP_DIR."
      fi
    fi
  done
  # The template adds a counter-app test that does not belong to this project.
  if [ "$HAD_TEMPLATE_TEST" = "0" ] && [ -f test/widget_test.dart ]; then
    rm -f test/widget_test.dart
  fi
  rm -rf "$BACKUP_DIR"

  [ "$CREATE_STATUS" -eq 0 ] || fail "'flutter create' failed (status $CREATE_STATUS). The project's own files were restored."
fi

# ---------------------------------------------------------------- 3. packages
step "3/6 flutter pub get"
flutter pub get || fail "'flutter pub get' failed. If a version cannot be resolved, see README.md, section 'Packages'."

# ---------------------------------------------------------------- 4. native configuration
step "4/6 Applying native configuration (tool/native)"
NATIVE_STATUS=0
if command -v python3 >/dev/null 2>&1; then
  python3 tool/native/apply_native_config.py "$PROJECT_DIR"
  NATIVE_STATUS=$?
  if [ "$NATIVE_STATUS" -eq 2 ]; then
    fail "Invalid option for the native configuration (see the message above)."
  fi
else
  NATIVE_STATUS=1
  echo "  WARNING: python3 was not found. Apply the snippets in tool/native/ by hand;"
  echo "           tool/native/README.md lists every change and where it goes."
fi

if [ "${SKIP_CHECKS:-0}" = "1" ]; then
  step "Done (SKIP_CHECKS=1: analyze and tests were not run)"
  exit "$NATIVE_STATUS"
fi

# ---------------------------------------------------------------- 5. analyze
step "5/6 flutter analyze"
flutter analyze
ANALYZE_STATUS=$?

# ---------------------------------------------------------------- 6. tests
step "6/6 flutter test"
flutter test
TEST_STATUS=$?

# ---------------------------------------------------------------- summary
printf '\n==> Summary\n'
if [ "$NATIVE_STATUS" -eq 0 ]; then echo "  native configuration : applied"; else echo "  native configuration : NEEDS MANUAL STEPS (see the warnings above)"; fi
if [ "$ANALYZE_STATUS" -eq 0 ]; then echo "  flutter analyze      : no issues"; else echo "  flutter analyze      : ISSUES FOUND (expected on the first run - see README.md, 'Verification status')"; fi
if [ "$TEST_STATUS" -eq 0 ]; then echo "  flutter test         : passed"; else echo "  flutter test         : FAILED"; fi
echo
echo "Next: README.md, section 'Run the app'."

if [ "$ANALYZE_STATUS" -ne 0 ] || [ "$TEST_STATUS" -ne 0 ] || [ "$NATIVE_STATUS" -ne 0 ]; then
  exit 1
fi
exit 0
